mapper.select:
SELECT p.id, p.category_id AS categoryId, c.name AS categoryName, p.name, p.subtitle, p.price, p.stock, p.sales, p.cover_image AS coverImage, p.status, p.create_time AS createTime, p.update_time AS updateTime FROM product p LEFT JOIN category c ON c.id = p.category_id AND c.deleted = 0 WHERE p.deleted = 0
AND p.category_id = #{categoryId}
AND p.status = #{status}
AND (p.name LIKE CONCAT('%', #{keyword}, '%') OR p.subtitle LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY p.create_time DESC
